/** Native profile render and reference layer/project formats. Only one bounded frame is in flight. */
final class DevGramProfileExport {
    private static final ExecutorService IO=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"devgram-profile-export");t.setDaemon(true);return t;});
    private final DevGramProfileEditor editor;private final ProfileActivity host;private final int account,mode,duration,fps;private final long uid;
    private final LinkedHashMap<String,View> views=new LinkedHashMap<>();private final ArrayList<ProfileExportPlan.Sheet> layers=new ArrayList<>();
    private FrameLayout overlay;private TextView progress;private volatile boolean cancelled;private boolean closed;private File directory,result;private int width,height,frame,layerIndex;private long begun,waitUntil;
    private final java.util.ArrayList<android.net.Uri> galleryFiles=new java.util.ArrayList<>();
    private final java.util.LinkedHashMap<String,MessageObject> clips=new java.util.LinkedHashMap<>();
    private ProfileGifEncoder gif;private ProfileApngEncoder apng;private ProfileVideoEncoder video;private final Runnable policy=()->{if(!allowed())cancel();};
    private String t(String s){return DevGramLocale.text(s);}
    static void show(DevGramProfileEditor editor){if(editor.host.getParentActivity()==null)return;String[] options={"PNG · "+DevGramLocale.text("Снимок профиля"),"GIF · "+DevGramLocale.text("Анимация профиля"),"APNG · "+DevGramLocale.text("Анимация профиля"),"MP4 · "+DevGramLocale.text("Видео профиля"),DevGramLocale.text("Слои · After Effects · Alight Motion")};editor.host.showDialog(new AlertDialog.Builder(editor.host.getParentActivity(),editor.host.getResourceProvider()).setTitle(DevGramLocale.text("Экспорт профиля")).setItems(options,(d,mode)->{if(!DevGramAppearanceAccess.check(editor.host,mode==4?"profile.export.layers":"profile.export"))return;if(mode>0&&mode<4){int[] seconds={5,10,15,30,60};editor.host.showDialog(new AlertDialog.Builder(editor.host.getParentActivity(),editor.host.getResourceProvider()).setTitle(DevGramLocale.text("Длительность анимации")).setItems(new String[]{"5 s","10 s","15 s","30 s","60 s"},(dialog,index)->start(editor,mode,seconds[index]*1000)).create());}else start(editor,mode,5000);}).create());}
    static void start(DevGramProfileEditor editor,int mode,int duration){if(editor.exporter!=null)return;DevGramProfileExport export=new DevGramProfileExport(editor,mode,duration);editor.exporter=export;export.start();}
    private DevGramProfileExport(DevGramProfileEditor editor,int mode,int duration){this.editor=editor;host=editor.host;account=host.getCurrentAccount();uid=editor.uid;this.mode=mode;this.duration=Math.max(1000,Math.min(60000,duration));fps=mode==1?20:30;}
    private boolean allowed(){return !cancelled&&!closed&&editor==host.devgramEditor&&host.getCurrentAccount()==account&&host.getUserConfig().getClientUserId()==uid&&DevGramProfileCustomization.enabled()&&DevGramProfilePolicy.allowed(uid,mode==4?"profile.export.layers":"profile.export");}
    private void start(){
        if(!allowed()){finish(false);return;}View source=host.getFragmentView();float scale=Math.min(1,(mode==1?480f:720f)/source.getWidth());width=Math.max(2,Math.round(source.getWidth()*scale)/2*2);height=Math.max(2,Math.round(source.getHeight()*scale)/2*2);if((long)width*height>4_000_000){fail();return;}
        directory=new File(ApplicationLoader.applicationContext.getCacheDir(),"devgram-profile-export/profile-"+System.currentTimeMillis());if(!directory.mkdirs()){fail();return;}
        overlay=new FrameLayout(host.getParentActivity());overlay.setBackgroundColor(0xdd121722);overlay.setClickable(true);overlay.setFocusableInTouchMode(true);LinearLayout content=DevGramStudioControls.column(overlay.getContext());content.setGravity(Gravity.CENTER);progress=DevGramStudioControls.text(overlay.getContext(),"Подготавливаю профиль…",18,true,host.getResourceProvider());progress.setTextColor(Color.WHITE);progress.setGravity(Gravity.CENTER);content.addView(progress);TextView stop=DevGramStudioControls.text(overlay.getContext(),"Отменить",16,true,host.getResourceProvider());stop.setTextColor(0xff83baff);stop.setPadding(20,24,20,24);stop.setGravity(Gravity.CENTER);stop.setOnClickListener(v->cancel());content.addView(stop);overlay.addView(content,LayoutHelper.createFrame(-1,-2,Gravity.CENTER,24,0,24,0));((ViewGroup)host.getParentActivity().getWindow().getDecorView()).addView(overlay,new ViewGroup.LayoutParams(-1,-1));overlay.requestFocus();overlay.setOnKeyListener((v,key,event)->{if(key==KeyEvent.KEYCODE_BACK){if(event.getAction()==KeyEvent.ACTION_UP)cancel();return true;}return false;});DevGramProfilePolicy.listen(policy);waitUntil=SystemClock.uptimeMillis()+8000;source.postDelayed(this::waitReady,250);
    }
    private void waitReady(){if(!allowed()){cancel();return;}if(!host.devgramExportReady()){if(SystemClock.uptimeMillis()<waitUntil){host.getFragmentView().postDelayed(this::waitReady,200);return;}fail();return;}for(String slot:new String[]{"banner","page"}){org.json.JSONObject asset=DevGramProfileMedia.resolve(editor.draft.document,editor.draft.target(account),slot);int message=asset==null?0:asset.optInt("message");if(message>0)DevGramProfileBackground.load(account,message,object->{if(object!=null&&object.getDocument()!=null&&(object.isVideo()||object.isGif()))clips.put(slot,object);});}
        views.putAll(host.devgramExportViews());collect(host.getFragmentView(),new HashSet<>(views.values()));View bar=views.remove("bar");if(bar!=null)views.put("bar",bar);if(mode==4)captureLayer();else if(mode==0){Bitmap bitmap=capture(null);if(bitmap==null){fail();return;}result=new File(directory,"DevGram-profile.png");IO.execute(()->{try(FileOutputStream output=new FileOutputStream(result)){if(!bitmap.compress(Bitmap.CompressFormat.PNG,100,output))throw new IOException();AndroidUtilities.runOnUIThread(()->finish(true));}catch(Exception error){FileLog.e(error);AndroidUtilities.runOnUIThread(this::fail);}finally{bitmap.recycle();}});}else{String suffix=mode==1?"gif":mode==2?"png":"mp4";result=new File(directory,"DevGram-profile."+suffix);IO.execute(()->{try{if(mode==1)gif=new ProfileGifEncoder(result,width,height);else if(mode==2)apng=new ProfileApngEncoder(result,width,height,duration*fps/1000);else video=new ProfileVideoEncoder(result,width,height,fps);AndroidUtilities.runOnUIThread(()->{begun=SystemClock.uptimeMillis();captureAnimation();});}catch(Exception error){FileLog.e(error);AndroidUtilities.runOnUIThread(this::fail);}});}}
    private void collect(View view,Set<View> known){if(view==null||known.contains(view)||view.getVisibility()!=View.VISIBLE||view.getWidth()<=0||view.getHeight()<=0)return;if(view instanceof ViewGroup&&((ViewGroup)view).getChildCount()>0){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)collect(group.getChildAt(i),known);}else views.put(String.format(java.util.Locale.US,"extra_%02d",views.size()),view);}
    private Bitmap capture(String only){
        if(!allowed())return null;View root=host.getFragmentView();IdentityHashMap<View,Integer> visibility=new IdentityHashMap<>();Drawable background=root.getBackground();IdentityHashMap<View,Drawable> surfaces=new IdentityHashMap<>();String oldPart=host.devgramExportPart;
        try{Bitmap bitmap=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.scale(width/(float)root.getWidth(),height/(float)root.getHeight());
            for(Map.Entry<String,View> entry:views.entrySet()){View view=entry.getValue();if(view==null)continue;visibility.put(view,view.getVisibility());if(entry.getKey().startsWith("private_phone_")||only!=null&&!entry.getKey().equals(only))view.setVisibility(View.INVISIBLE);}
            if(only!=null){View view=views.get(only);for(View parent=view;parent!=null&&parent!=root;){Integer visible=visibility.get(parent);if(visible!=null)parent.setVisibility(visible);parent=parent.getParent() instanceof View?(View)parent.getParent():null;}for(View surface:host.devgramExportSurfaces()){surfaces.put(surface,surface.getBackground());surface.setBackground(null);}root.setBackground(null);host.devgramExportPart=only;}
            editor.exportChrome(true);root.draw(canvas);return bitmap;
        }catch(Throwable error){FileLog.e(error);return null;}finally{host.devgramExportPart=oldPart;root.setBackground(background);for(Map.Entry<View,Drawable> surface:surfaces.entrySet())surface.getKey().setBackground(surface.getValue());for(Map.Entry<View,Integer> entry:visibility.entrySet())entry.getKey().setVisibility(entry.getValue());editor.exportChrome(false);}
    }
    private void captureAnimation(){if(!allowed()){cancel();return;}Bitmap bitmap=capture(null);if(bitmap==null){fail();return;}int index=frame;progress.setText(t("Записываю анимацию…")+" "+(100*index/(duration*fps/1000))+"%");IO.execute(()->{try{if(cancelled){closeEncoders();bitmap.recycle();return;}if(gif!=null)gif.addFrame(bitmap,1000/fps);else if(apng!=null)apng.addFrame(bitmap,1000/fps);else video.addFrame(bitmap,index*1_000_000L/fps);bitmap.recycle();AndroidUtilities.runOnUIThread(()->{if(!allowed()){cancel();return;}frame++;if(frame>=duration*fps/1000){IO.execute(()->{try{if(gif!=null)gif.finish();else if(apng!=null)apng.finish();else video.finish(frame*1_000_000L/fps);AndroidUtilities.runOnUIThread(()->finish(true));}catch(Exception error){FileLog.e(error);AndroidUtilities.runOnUIThread(this::fail);}});}else host.getFragmentView().postDelayed(this::captureAnimation,Math.max(0,begun+frame*1000L/fps-SystemClock.uptimeMillis()));});}catch(Exception error){bitmap.recycle();FileLog.e(error);closeEncoders();AndroidUtilities.runOnUIThread(this::fail);}});}
    private void captureLayer(){if(!allowed()){cancel();return;}ArrayList<String> names=new ArrayList<>();names.add("background");for(Map.Entry<String,View> entry:views.entrySet())if(entry.getValue()!=null&&entry.getValue().getVisibility()==View.VISIBLE&&!entry.getKey().startsWith("private_phone_"))names.add(entry.getKey());if(layerIndex>=names.size()){IO.execute(this::pack);return;}String name=names.get(layerIndex++);progress.setText(t("Снимаю профиль слоями…")+" "+layerIndex+" / "+names.size());Bitmap bitmap=capture(name);if(bitmap==null){fail();return;}IO.execute(()->{try{int[] pixels=new int[width*height];bitmap.getPixels(pixels,0,width,0,0,width,height);int[] bounds=ProfileExportPlan.bounds(pixels,width,height);if(bounds!=null){int x=bounds[0],y=bounds[1],w=bounds[2]-x+1,h=bounds[3]-y+1;Bitmap crop=Bitmap.createBitmap(bitmap,x,y,w,h);try(FileOutputStream output=new FileOutputStream(new File(directory,name+".png"))){if(!crop.compress(Bitmap.CompressFormat.PNG,100,output))throw new IOException();}finally{if(crop!=bitmap)crop.recycle();}layers.add(new ProfileExportPlan.Sheet(name,x,y,w,h));}bitmap.recycle();AndroidUtilities.runOnUIThread(this::captureLayer);}catch(Exception error){bitmap.recycle();FileLog.e(error);AndroidUtilities.runOnUIThread(this::fail);}});}
    private void pack(){try{if(cancelled)return;String color="#ff101526";int scene=duration;java.util.HashMap<String,ProfileExportAm.Piece> videoPieces=new java.util.HashMap<>();
            for(java.util.Map.Entry<String,MessageObject> clip:clips.entrySet()){
                MessageObject object=clip.getValue();File source=FileLoader.getInstance(account).getPathToMessage(object.messageOwner);if(!source.isFile()||source.length()>128L*1024*1024)continue;String parent=clip.getKey().equals("page")?"background":"header",name=clip.getKey().equals("page")?"bg_video":"banner_video";ProfileExportPlan.Sheet base=null;int position=0;for(int i=0;i<layers.size();i++)if(layers.get(i).name.equals(parent)){base=layers.get(i);position=i+1;break;}if(base==null)continue;
                String mime=object.getDocument().mime_type;if(!"video/mp4".equals(mime))continue;File target=new File(directory,name+".mp4");try(InputStream input=new FileInputStream(source);OutputStream output=new FileOutputStream(target)){byte[] bytes=new byte[65536];int count;while((count=input.read(bytes))!=-1){if(cancelled)throw new IOException("cancelled");output.write(bytes,0,count);}}
                android.media.MediaMetadataRetriever metadata=new android.media.MediaMetadataRetriever();int mw=base.width,mh=base.height;long us=5000000;try{metadata.setDataSource(target.getPath());mw=Integer.parseInt(metadata.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH));mh=Integer.parseInt(metadata.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_VIDEO_HEIGHT));us=Long.parseLong(metadata.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION))*1000;}finally{metadata.release();}scene=Math.max(scene,(int)Math.min(60000,us/1000));android.net.Uri uri=gallery(target,mime);layers.add(position,new ProfileExportPlan.Sheet(name,base.x,base.y,base.width,base.height,target.getName()));videoPieces.put(name,new ProfileExportAm.Piece(name,uri.toString(),target.getName(),mime,target.length(),base.x,base.y,base.width,base.height,mw,mh,us));
            }
            ArrayList<ProfileExportAm.Piece> pieces=new ArrayList<>();for(ProfileExportPlan.Sheet layer:layers){if(videoPieces.containsKey(layer.name)){pieces.add(videoPieces.get(layer.name));continue;}File file=new File(directory,layer.name+".png");android.net.Uri uri=gallery(file,"image/png");pieces.add(new ProfileExportAm.Piece(layer.name,uri.toString(),file.getName(),file.length(),layer.x,layer.y,layer.width,layer.height));}write(new File(directory,"manifest.json"),ProfileExportPlan.manifest(width,height,color,layers));write(new File(directory,"project.jsx"),ProfileExportAe.script("DevGram",width,height,30,scene,color,layers));String xml=ProfileExportAm.project("DevGram",width,height,30,scene,color,pieces,System.currentTimeMillis());File project=new File(directory,"DevGram-profile.xml");write(project,xml);gallery(project,"application/xml");result=new File(directory,"DevGram-profile-layers.zip");File[] files=directory.listFiles();try(ZipOutputStream zip=new ZipOutputStream(new BufferedOutputStream(new FileOutputStream(result)))){byte[] buffer=new byte[65536];for(File file:files){if(file.equals(result)||!file.isFile())continue;zip.putNextEntry(new ZipEntry(file.getName()));try(InputStream input=new FileInputStream(file)){int count;while((count=input.read(buffer))!=-1){if(cancelled)throw new IOException("cancelled");zip.write(buffer,0,count);}}zip.closeEntry();}}AndroidUtilities.runOnUIThread(()->finish(true));}catch(Exception error){FileLog.e(error);AndroidUtilities.runOnUIThread(this::fail);}}
    private android.net.Uri gallery(File file,String mime)throws IOException{if(android.os.Build.VERSION.SDK_INT<29)return FileProvider.getUriForFile(ApplicationLoader.applicationContext,ApplicationLoader.getApplicationId()+".provider",file);android.content.ContentResolver resolver=ApplicationLoader.applicationContext.getContentResolver();android.content.ContentValues values=new android.content.ContentValues();values.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME,directory.getName()+"-"+file.getName());values.put(android.provider.MediaStore.MediaColumns.MIME_TYPE,mime);values.put(android.provider.MediaStore.MediaColumns.RELATIVE_PATH,mime.startsWith("image/")?"Pictures/DevGram":mime.startsWith("video/")?"Movies/DevGram":"Download/DevGram");values.put(android.provider.MediaStore.MediaColumns.IS_PENDING,1);android.net.Uri collection=mime.startsWith("image/")?android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI:mime.startsWith("video/")?android.provider.MediaStore.Video.Media.EXTERNAL_CONTENT_URI:android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI;android.net.Uri uri=resolver.insert(collection,values);if(uri==null)throw new IOException("export_gallery");try(OutputStream output=resolver.openOutputStream(uri);InputStream input=new FileInputStream(file)){if(output==null)throw new IOException();byte[] buffer=new byte[65536];int count;while((count=input.read(buffer))!=-1)output.write(buffer,0,count);}catch(Exception error){resolver.delete(uri,null,null);throw new IOException(error);}values.clear();values.put(android.provider.MediaStore.MediaColumns.IS_PENDING,0);resolver.update(uri,values,null,null);galleryFiles.add(uri);return uri;}
    private static void write(File file,String text)throws IOException{try(FileOutputStream stream=new FileOutputStream(file)){stream.write(text.getBytes("UTF-8"));}}
    private void closeEncoders(){try{if(gif!=null)gif.close();if(apng!=null)apng.close();if(video!=null)video.close();}catch(Exception error){FileLog.e(error);}}
    private static void drop(File file){if(file==null)return;if(file.isDirectory()){File[] children=file.listFiles();if(children!=null)for(File child:children)drop(child);}file.delete();}
    private void fail(){if(closed)return;finish(false);BulletinFactory.of(host).createErrorBulletin(t("Не удалось экспортировать профиль. Дождитесь загрузки медиа и проверьте свободное место.")).show();}
    void cancel(){if(closed)return;cancelled=true;finish(false);}
    private void finish(boolean success){if(closed)return;boolean share=success&&allowed();closed=true;DevGramProfilePolicy.unlisten(policy);if(overlay!=null&&overlay.getParent() instanceof ViewGroup)((ViewGroup)overlay.getParent()).removeView(overlay);if(editor.exporter==this)editor.exporter=null;IO.execute(()->{closeEncoders();if(!share){for(android.net.Uri uri:galleryFiles)try{ApplicationLoader.applicationContext.getContentResolver().delete(uri,null,null);}catch(Exception ignored){}drop(directory);}});if(share&&result!=null&&host.getParentActivity()!=null){String mime=mode==4?"application/zip":mode==1?"image/gif":mode==3?"video/mp4":"image/png";try{Intent intent=new Intent(Intent.ACTION_SEND).setType(mime).putExtra(Intent.EXTRA_STREAM,FileProvider.getUriForFile(host.getParentActivity(),ApplicationLoader.getApplicationId()+".provider",result)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);host.getParentActivity().startActivity(Intent.createChooser(intent,t("Экспорт профиля")));}catch(Exception error){FileLog.e(error);}}}
}
